import {canvas,text,wrap,e} from '../../../embed/definitions/_lab.js';
export {e};
// SVG text coordinates are baselines: row rules use y - 24 to clear the heading glyphs.
export const DIMENSIONS=[
  {id:'terms',label:'Terminology',standard:'Request / owner / ready',why:'A named vocabulary for a handoff'},
  {id:'format',label:'Interface format',standard:'Structured record',why:'The artefact another team receives'},
  {id:'method',label:'Internal method',standard:'Weekly batch',why:'How a team does its own work'},
  {id:'rule',label:'Decision rule',standard:'Lead approval',why:'Who can accept a change'}
];
export const MODES={local:'Local choices',mapped:'Named mappings',common:'Common standard'};
const team=(name,work,requirements)=>({name,work,requirements});
export const SCENARIOS={
  studio:{name:'A varied product studio',description:'Research, delivery and support need different ways of working, but pass work between them.',teams:[team('Research','small experiments',['question','notebook','continuous','team consent']),team('Delivery','product changes',['request','record','weekly','lead approval']),team('Support','urgent cases',['case','ticket','continuous','on-call decision'])],needs:[['terms','format'],['terms','format','rule'],['terms','method']],jobs:[12,20,30],handoffs:[12,10,8]},
  shared:{name:'A shared operations service',description:'Three service desks do similar work and exchange many cases. Their local requirements already fit the proposed standards.',teams:[team('North desk','routine requests',['request','record','weekly','lead approval']),team('Central desk','routine requests',['request','record','weekly','lead approval']),team('South desk','routine requests',['request','record','weekly','lead approval'])],needs:[['terms','format','method','rule'],['terms','format','method','rule'],['terms','format','method','rule']],jobs:[24,24,24],handoffs:[24,24,24]},
  islands:{name:'Mostly independent specialists',description:'A workshop, a research group and a help desk rarely exchange work. Internal variety has little coordination cost.',teams:[team('Workshop','made-to-order pieces',['order','drawing','weekly','lead approval']),team('Research','field studies',['question','notebook','continuous','team consent']),team('Help desk','urgent cases',['case','ticket','continuous','on-call decision'])],needs:[['terms','format'],['terms','format'],['terms','rule']],jobs:[20,20,30],handoffs:[1,1,0]}
};
const STANDARD=['request','record','weekly','lead approval'];
export function create(scenario='studio') {const s=SCENARIOS[scenario];if(!s)throw Error('Unknown scenario.');return {scenario,policy:{terms:'local',format:'local',method:'local',rule:'local'},jobs:[...s.jobs],handoffs:[...s.handoffs],translation:4,mappedTranslation:1,allowance:6,setup:12,mappingSetup:8,workaround:[1,2,5,3]};}
const numberSchema=(maximum=200)=>({type:'integer',minimum:0,maximum});
const list=(length,maximum)=>({type:'array',minItems:length,maxItems:length,items:numberSchema(maximum)});
const obj=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
export const stateSchema=obj({scenario:{type:'string',enum:Object.keys(SCENARIOS)},policy:obj(Object.fromEntries(DIMENSIONS.map(d=>[d.id,{type:'string',enum:Object.keys(MODES)}]))),jobs:list(3,100),handoffs:list(3,100),translation:numberSchema(30),mappedTranslation:numberSchema(30),allowance:numberSchema(120),setup:numberSchema(120),mappingSetup:numberSchema(120),workaround:list(4,30)});
export function validate(s){
  if(!s||typeof s!=='object'||Array.isArray(s)||Object.keys(s).length!==Object.keys(stateSchema.properties).length||Object.keys(s).some(k=>!Object.hasOwn(stateSchema.properties,k)))throw Error('Expected a complete consistency experiment.');
  if(!Object.hasOwn(SCENARIOS,s.scenario)||!s.policy||Object.keys(s.policy).length!==4||DIMENSIONS.some(d=>!Object.hasOwn(MODES,s.policy[d.id])))throw Error('Unknown scenario or standards policy.');
  for(const [key,max,length] of [['jobs',100,3],['handoffs',100,3],['workaround',30,4]])if(!Array.isArray(s[key])||s[key].length!==length||s[key].some(n=>!Number.isInteger(n)||n<0||n>max))throw Error('Invalid '+key+'.');
  for(const [key,max] of [['translation',30],['mappedTranslation',30],['allowance',120],['setup',120],['mappingSetup',120]])if(!Number.isInteger(s[key])||s[key]<0||s[key]>max)throw Error('Invalid '+key+'.');
  return s;
}
export function project(s){
  validate(s);const scenario=SCENARIOS[s.scenario];
  const teams=scenario.teams.map((t,i)=>({...t,jobs:s.jobs[i],workarounds:DIMENSIONS.flatMap((d,j)=>s.policy[d.id]==='common'&&t.requirements[j]!==STANDARD[j]?[{dimension:d.label,requirement:t.requirements[j],standard:STANDARD[j],minutes:s.jobs[i]*s.workaround[j],perItem:s.workaround[j]}]:[])}));
  const links=scenario.needs.map((needs,i)=>{const from=i,to=(i+1)%3;const gaps=needs.flatMap(id=>{const j=DIMENSIONS.findIndex(d=>d.id===id),mode=s.policy[id];const mismatch=mode!=='common'&&teams[from].requirements[j]!==teams[to].requirements[j];return mismatch?[{dimension:DIMENSIONS[j].label,from:teams[from].requirements[j],to:teams[to].requirements[j],minutes:mode==='mapped'?s.mappedTranslation:s.translation,mode}]:[];});const perHandoff=gaps.reduce((n,g)=>n+g.minutes,0),count=s.handoffs[i],success=perHandoff<=s.allowance;return{from:teams[from].name,to:teams[to].name,needs,gaps,count,perHandoff,success,completed:success?count:0,requiredMinutes:perHandoff*count,spentMinutes:success?perHandoff*count:0};});
  const setup=DIMENSIONS.reduce((n,d)=>n+(s.policy[d.id]==='common'?s.setup*3:s.policy[d.id]==='mapped'?s.mappingSetup*3:0),0),workaround=teams.reduce((n,t)=>n+t.workarounds.reduce((sum,w)=>sum+w.minutes,0),0),translation=links.reduce((n,l)=>n+l.spentMinutes,0),requested=links.reduce((n,l)=>n+l.count,0),completed=links.reduce((n,l)=>n+l.completed,0);
  return{scenario,teams,links,setup,workaround,translation,requiredTranslation:links.reduce((n,l)=>n+l.requiredMinutes,0),effort:setup+workaround+translation,requested,completed,blocked:requested-completed};
}
export function replayPolicy(current,pinned){return project({...structuredClone(current),policy:structuredClone(pinned.policy)});}
export function summary(r){return `${r.completed} of ${r.requested} handoffs fit the translation allowance; ${r.blocked} wait. ${r.effort} minutes: ${r.setup} setup + ${r.translation} completed-handoff translation + ${r.workaround} local workarounds.`;}
export function describe(s,pinned){const r=project(s);return `# How much consistency is enough?\n\n${r.scenario.name}\n\n${summary(r)}\n\n${DIMENSIONS.map(d=>`- ${d.label}: ${MODES[s.policy[d.id]]}${s.policy[d.id]==='common'?` (${d.standard})`:''}`).join('\n')}\n\n${r.links.map(l=>`- ${l.from} → ${l.to}: ${l.count} handoffs, ${l.perHandoff} translation minutes each; ${l.success?'within':'above'} the ${s.allowance}-minute allowance.`).join('\n')}\n\n${r.teams.map(t=>`- ${t.name}: ${t.jobs} items. ${t.workarounds.map(w=>`${w.dimension}: ${w.minutes} workaround minutes`).join('; ')||'No local workarounds.'}`).join('\n')}\n\nAssumptions: direct translation ${s.translation} min per mismatch; mapped translation ${s.mappedTranslation}; common setup ${s.setup} min per team and dimension; mapping setup ${s.mappingSetup}. Workaround minutes per item: ${s.workaround.join(', ')} (terminology, format, method, rule). Setup is charged once per shown period; the model assumes translations preserve meaning and workarounds preserve local requirements. Waiting handoffs consume no translation time.\n\n${pinned?`Pinned policy, replayed under these teams, workload and costs: ${summary(replayPolicy(s,pinned))}\n\n`:''}Fictional accounting model, not an empirical prediction. Inspired by John Cutler, [Minimally Viable Consistency](https://cutlefish.substack.com/p/tbm-421-minimally-viable-consistency).\n`;}
export function render(s,ctx={}){const r=project(s);return{summary:summary(r),svg:canvas('How much consistency is enough?',`${r.scenario.name} · ${r.completed}/${r.requested} handoffs pass`,ctx,({w,c,top})=>{let y=top,body='';const chars=Math.max(20,Math.floor((w-48)/9));const add=(value,size=18,color=c.ink)=>{body+=text(24,y,value,{width:chars,size,color});y+=wrap(value,chars).length*size*1.4+14;};add(DIMENSIONS.map(d=>`${d.label}: ${MODES[s.policy[d.id]]}`).join(' · '),16,c.accent);for(const l of r.links){body+=`<path d="M24 ${y-24} H${w-24}" stroke="${e(c.line)}"/>`;add(`${l.from} → ${l.to}`,20);add(`${l.completed}/${l.count} pass · ${l.perHandoff} min translation each / ${s.allowance} min allowed`,16);add(l.gaps.map(g=>`${g.dimension}: ${g.from} → ${g.to} (${g.minutes} min)`).join('; ')||'Required fields already compatible.',16,c.muted);}add(`${r.effort} minutes of effort`,24,c.accent);add(`${r.setup} setup + ${r.translation} translation + ${r.workaround} workarounds. Waiting handoffs: ${r.blocked}.`,16);add('Fictional requirements and editable time assumptions. A passed handoff fits the allowance; it does not imply useful work.',14,c.muted);return{body,end:y};})};}
